WITH PARAMS AS ( SELECT CASE WHEN LEFT(TRIM(COALESCE(:VAR_DATA_INICIO, '')), 10) REGEXP '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN STR_TO_DATE(LEFT(TRIM(:VAR_DATA_INICIO), 10), '%d/%m/%Y') WHEN LEFT(TRIM(COALESCE(:VAR_DATA_INICIO, '')), 10) REGEXP '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN DATE(LEFT(TRIM(:VAR_DATA_INICIO), 10)) ELSE NULL END AS DT_INI_IN, CASE WHEN LEFT(TRIM(COALESCE(:VAR_DATA_FIM, '')), 10) REGEXP '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN STR_TO_DATE(LEFT(TRIM(:VAR_DATA_FIM), 10), '%d/%m/%Y') WHEN LEFT(TRIM(COALESCE(:VAR_DATA_FIM, '')), 10) REGEXP '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN DATE(LEFT(TRIM(:VAR_DATA_FIM), 10)) ELSE NULL END AS DT_FIM_IN ), D AS ( SELECT LEAST(DT_INI, DT_FIM) AS DT_INI, GREATEST(DT_INI, DT_FIM) AS DT_FIM, YEAR(GREATEST(DT_INI, DT_FIM)) AS ANO FROM ( SELECT COALESCE(DT_FIM_IN, CURDATE()) AS DT_FIM, COALESCE(DT_INI_IN, MAKEDATE(YEAR(COALESCE(DT_FIM_IN, CURDATE())), 1)) AS DT_INI FROM PARAMS ) X ), N12 AS ( SELECT 1 AS N UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL SELECT 12 ), M AS ( SELECT N, CASE WHEN LAST_DAY(MAKEDATE(ANO, 1) + INTERVAL (N - 1) MONTH) >= DT_INI AND MAKEDATE(ANO, 1) + INTERVAL (N - 1) MONTH <= DT_FIM THEN 1 ELSE 0 END AS ATIVO, GREATEST(MAKEDATE(ANO, 1) + INTERVAL (N - 1) MONTH, DT_INI) AS DE, LEAST(LAST_DAY(MAKEDATE(ANO, 1) + INTERVAL (N - 1) MONTH), DT_FIM) AS ATE FROM N12 CROSS JOIN D ), vinc AS ( SELECT DISTINCT d.ID, d.ORDEM, TRIM(c.ID_CONTA_CONTABIL) AS CONTA FROM DET_DRE_TW d INNER JOIN CAD_CONTA_DRE_TW c ON c.ID_DET_DRE_TW = d.ID WHERE d.ID_ESTR_DRE_TW = 7 ), qtd AS ( SELECT ID, COUNT(*) AS Q FROM vinc GROUP BY ID ), dono AS ( SELECT v.ID, v.CONTA, ROW_NUMBER() OVER (PARTITION BY v.CONTA ORDER BY q.Q ASC, v.ORDEM DESC, v.ID DESC) AS RN FROM vinc v INNER JOIN qtd q ON q.ID = v.ID ), saldos AS ( SELECT B.CTACTB, M.N, SUM(B.VLRLANC) AS V FROM IMP_BASE_BALANCETE B INNER JOIN M ON M.ATIVO = 1 AND DATE(B.REFERENCIA) <= M.ATE WHERE B.CODEMP = :VAR_EMPRESA_DRE GROUP BY B.CTACTB, M.N ), LM AS ( SELECT v.ID, s.N, SUM(s.V) AS V, SUM(CASE WHEN o.RN = 1 THEN s.V ELSE 0 END) AS VE FROM vinc v INNER JOIN saldos s ON s.CTACTB = v.CONTA INNER JOIN dono o ON o.ID = v.ID AND o.CONTA = v.CONTA GROUP BY v.ID, s.N ) SELECT d.ORDEM, d.HIERARQUIA, d.DESCRICAO, d.FORMATACAO, d.SINAL, CASE WHEN (SELECT ATIVO FROM M WHERE N = 1) = 1 THEN IFNULL(SUM(CASE WHEN LM.N = 1 THEN LM.V END), 0) END AS VALOR_JAN, CASE WHEN (SELECT ATIVO FROM M WHERE N = 2) = 1 THEN IFNULL(SUM(CASE WHEN LM.N = 2 THEN LM.V END), 0) END AS VALOR_FEV, CASE WHEN (SELECT ATIVO FROM M WHERE N = 3) = 1 THEN IFNULL(SUM(CASE WHEN LM.N = 3 THEN LM.V END), 0) END AS VALOR_MAR, CASE WHEN (SELECT ATIVO FROM M WHERE N = 4) = 1 THEN IFNULL(SUM(CASE WHEN LM.N = 4 THEN LM.V END), 0) END AS VALOR_ABR, CASE WHEN (SELECT ATIVO FROM M WHERE N = 5) = 1 THEN IFNULL(SUM(CASE WHEN LM.N = 5 THEN LM.V END), 0) END AS VALOR_MAI, CASE WHEN (SELECT ATIVO FROM M WHERE N = 6) = 1 THEN IFNULL(SUM(CASE WHEN LM.N = 6 THEN LM.V END), 0) END AS VALOR_JUN, CASE WHEN (SELECT ATIVO FROM M WHERE N = 7) = 1 THEN IFNULL(SUM(CASE WHEN LM.N = 7 THEN LM.V END), 0) END AS VALOR_JUL, CASE WHEN (SELECT ATIVO FROM M WHERE N = 8) = 1 THEN IFNULL(SUM(CASE WHEN LM.N = 8 THEN LM.V END), 0) END AS VALOR_AGO, CASE WHEN (SELECT ATIVO FROM M WHERE N = 9) = 1 THEN IFNULL(SUM(CASE WHEN LM.N = 9 THEN LM.V END), 0) END AS VALOR_SET, CASE WHEN (SELECT ATIVO FROM M WHERE N = 10) = 1 THEN IFNULL(SUM(CASE WHEN LM.N = 10 THEN LM.V END), 0) END AS VALOR_OUT, CASE WHEN (SELECT ATIVO FROM M WHERE N = 11) = 1 THEN IFNULL(SUM(CASE WHEN LM.N = 11 THEN LM.V END), 0) END AS VALOR_NOV, CASE WHEN (SELECT ATIVO FROM M WHERE N = 12) = 1 THEN IFNULL(SUM(CASE WHEN LM.N = 12 THEN LM.V END), 0) END AS VALOR_DEZ, CASE WHEN (SELECT ATIVO FROM M WHERE N = 1) = 1 THEN IFNULL(SUM(CASE WHEN LM.N = 1 THEN LM.VE END), 0) END AS EXC_JAN, CASE WHEN (SELECT ATIVO FROM M WHERE N = 2) = 1 THEN IFNULL(SUM(CASE WHEN LM.N = 2 THEN LM.VE END), 0) END AS EXC_FEV, CASE WHEN (SELECT ATIVO FROM M WHERE N = 3) = 1 THEN IFNULL(SUM(CASE WHEN LM.N = 3 THEN LM.VE END), 0) END AS EXC_MAR, CASE WHEN (SELECT ATIVO FROM M WHERE N = 4) = 1 THEN IFNULL(SUM(CASE WHEN LM.N = 4 THEN LM.VE END), 0) END AS EXC_ABR, CASE WHEN (SELECT ATIVO FROM M WHERE N = 5) = 1 THEN IFNULL(SUM(CASE WHEN LM.N = 5 THEN LM.VE END), 0) END AS EXC_MAI, CASE WHEN (SELECT ATIVO FROM M WHERE N = 6) = 1 THEN IFNULL(SUM(CASE WHEN LM.N = 6 THEN LM.VE END), 0) END AS EXC_JUN, CASE WHEN (SELECT ATIVO FROM M WHERE N = 7) = 1 THEN IFNULL(SUM(CASE WHEN LM.N = 7 THEN LM.VE END), 0) END AS EXC_JUL, CASE WHEN (SELECT ATIVO FROM M WHERE N = 8) = 1 THEN IFNULL(SUM(CASE WHEN LM.N = 8 THEN LM.VE END), 0) END AS EXC_AGO, CASE WHEN (SELECT ATIVO FROM M WHERE N = 9) = 1 THEN IFNULL(SUM(CASE WHEN LM.N = 9 THEN LM.VE END), 0) END AS EXC_SET, CASE WHEN (SELECT ATIVO FROM M WHERE N = 10) = 1 THEN IFNULL(SUM(CASE WHEN LM.N = 10 THEN LM.VE END), 0) END AS EXC_OUT, CASE WHEN (SELECT ATIVO FROM M WHERE N = 11) = 1 THEN IFNULL(SUM(CASE WHEN LM.N = 11 THEN LM.VE END), 0) END AS EXC_NOV, CASE WHEN (SELECT ATIVO FROM M WHERE N = 12) = 1 THEN IFNULL(SUM(CASE WHEN LM.N = 12 THEN LM.VE END), 0) END AS EXC_DEZ, (SELECT DT_INI FROM D) AS DATA_INICIO_USADA, (SELECT DT_FIM FROM D) AS DATA_FIM_USADA, (SELECT ANO FROM D) AS ANO_ATU, (SELECT COUNT(*) FROM IMP_BASE_BALANCETE WHERE CODEMP = :VAR_EMPRESA_DRE) AS LANC_EMPRESA, (SELECT COUNT(*) FROM IMP_BASE_BALANCETE WHERE CODEMP = :VAR_EMPRESA_DRE AND DATE(REFERENCIA) BETWEEN (SELECT DT_INI FROM D) AND (SELECT DT_FIM FROM D)) AS LANC_PERIODO, CASE WHEN (SELECT DT_INI_IN FROM PARAMS) IS NULL OR (SELECT DT_FIM_IN FROM PARAMS) IS NULL THEN 0 ELSE 1 END AS DATAS_OK FROM DET_DRE_TW d LEFT JOIN LM ON LM.ID = d.ID WHERE d.ID_ESTR_DRE_TW = 7 GROUP BY d.ID, d.ORDEM, d.HIERARQUIA, d.DESCRICAO, d.FORMATACAO, d.SINAL ORDER BY d.ORDEM;